import java.text.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner in = new Scanner(System.in);
        Locale locale = Locale.forLanguageTag(in.nextLine().trim());
        MessageFormat mf = new MessageFormat("{0} punya {1,choice,0#belum ada poin|1#1 poin|1<{1,number,integer} poin}", locale);
        while (in.hasNextLine()) {
            String[] d = in.nextLine().trim().split(" ");
            String nama = d[0];
            int poin = Integer.parseInt(d[1]);
            System.out.println(mf.format(new Object[]{nama, poin}));
        }
    }
}
